// This file is generated by AI.

// 仓库页: git 初始化 / 暂存 / 提交 / 历史入口。

import { Button, Input, Textarea } from '@fluentui/react-components';
import {
  AddRegular,
  ArrowUndoRegular,
  BranchForkRegular,
  CheckmarkRegular,
  HistoryRegular,
  SelectAllOnRegular,
} from '@fluentui/react-icons';
import { useEffect, useRef, useState } from 'react';

import {
  gitCommit,
  gitDiscard,
  gitDiscardAll,
  gitInit,
  gitSetIdentity,
  gitStage,
  gitStageAll,
  gitUnstage,
  gitUnstageAll,
  type GitFileStatus,
} from '../commands/git';
import { openGitDiff } from '../git/diff';
import { refreshGitStatus } from '../git/status';
import { STATUS_CLASS } from '../git/util';
import { useAppStore } from '../state/store';
import { middleEllipsis } from './FileTree';
import { GitHistoryDialog } from './GitHistoryDialog';

/** 默认 .gitignore: 仅跟踪 game/config.txt 与 game/scene/**\/*.txt (含嵌套目录) */
const DEFAULT_GITIGNORE = '*\n!game/\n!game/config.txt\n!game/scene/\n!game/scene/**/\n!game/scene/**/*.txt\n';

/** 提交文本草稿在会话内跨切换保留 */
let commitDraft = '';

export function RepositoryTab() {
  const projectPath = useAppStore((s) => s.projectPath);
  const gitStatus = useAppStore((s) => s.gitStatus);

  const [initOpen, setInitOpen] = useState(false);
  const [gitignore, setGitignore] = useState(DEFAULT_GITIGNORE);
  const [message, setMessage] = useState(commitDraft);
  const commitRef = useRef<HTMLTextAreaElement>(null);
  const [identityOpen, setIdentityOpen] = useState(false);
  const [identity, setIdentity] = useState({ name: '', email: '' });
  const [historyOpen, setHistoryOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [menu, setMenu] = useState<{
    file: GitFileStatus;
    section: 'staged' | 'unstaged';
    x: number;
    y: number;
  } | null>(null);

  // 进入仓库页时刷新
  useEffect(() => {
    if (projectPath) void refreshGitStatus(projectPath);
  }, [projectPath]);

  useEffect(() => {
    if (!menu) return;
    const close = () => setMenu(null);
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('scroll', close, { capture: true });
    window.addEventListener('resize', close);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('scroll', close, { capture: true });
      window.removeEventListener('resize', close);
    };
  }, [menu]);

  // Esc 关闭打开的模态框 (初始化 / 身份 / 错误弹窗)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      if (menu) {
        setMenu(null);
      } else if (initOpen) {
        setInitOpen(false);
        setError(null);
      } else if (identityOpen) {
        setIdentityOpen(false);
        setError(null);
      } else if (error) {
        setError(null);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [menu, initOpen, identityOpen, error]);

  if (!projectPath) return <div className="repository empty">未打开项目</div>;
  if (!gitStatus) return <div className="repository empty">加载中…</div>;

  const run = async (fn: () => Promise<unknown>): Promise<boolean> => {
    if (busy) return false;
    setBusy(true);
    try {
      await fn();
      await refreshGitStatus(projectPath);
      return true;
    } catch (e) {
      setError(String(e));
      return false;
    } finally {
      setBusy(false);
    }
  };

  const commitDraftUpdate = (v: string) => {
    commitDraft = v;
    setMessage(v);
  };

  // 提交编辑器随内容自动增高
  const autoGrow = () => {
    const el = commitRef.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
  };
  useEffect(() => {
    autoGrow();
  }, []);

  const doCommit = () =>
    run(() => gitCommit(projectPath, message.trim())).then((ok) => {
      if (ok) {
        commitDraft = '';
        setMessage('');
      }
    });

  const tryCommit = () => {
    if (!message.trim()) return;
    if (!gitStatus.identity) {
      setIdentity({ name: '', email: '' });
      setIdentityOpen(true);
      return;
    }
    void doCommit();
  };

  const submitIdentity = () =>
    run(() => gitSetIdentity(projectPath, identity.name.trim(), identity.email.trim())).then((ok) => {
      if (ok) {
        setIdentityOpen(false);
        void doCommit();
      }
    });

  const fileRow = (file: GitFileStatus, section: 'staged' | 'unstaged') => {
    const cls = STATUS_CLASS[file.status] ?? '';
    return (
      <button
        key={`${section}-${file.path}`}
        className="git-file-item"
        onClick={() => openGitDiff(file.path, section)}
        onContextMenu={(e) => {
          e.preventDefault();
          setMenu({
            file,
            section,
            x: Math.min(e.clientX, window.innerWidth - 200),
            y: Math.min(e.clientY, window.innerHeight - 180),
          });
        }}
        title={file.path}
      >
        <span className={`git-file-status ${cls}`}>{file.status}</span>
        <span className="git-file-name">{middleEllipsis(file.path, 40)}</span>
        <span className="git-file-stats">
          {file.additions > 0 ? <em className="git-add">+{file.additions}</em> : null}
          {file.deletions > 0 ? <em className="git-del">-{file.deletions}</em> : null}
        </span>
      </button>
    );
  };

  const menuItems = menu
    ? menu.section === 'staged'
      ? [
          {
            label: '暂存全部',
            icon: <SelectAllOnRegular />,
            onClick: () => run(() => gitStageAll(projectPath)),
          },
          {
            label: '放弃',
            icon: <ArrowUndoRegular />,
            onClick: () => run(() => gitUnstage(projectPath, [menu.file.path])),
          },
          {
            label: '放弃全部',
            icon: <ArrowUndoRegular />,
            onClick: () => run(() => gitUnstageAll(projectPath)),
          },
        ]
      : [
          {
            label: '暂存',
            icon: <AddRegular />,
            onClick: () => run(() => gitStage(projectPath, [menu.file.path])),
          },
          {
            label: '暂存全部',
            icon: <SelectAllOnRegular />,
            onClick: () => run(() => gitStageAll(projectPath)),
          },
          {
            label: '放弃',
            icon: <ArrowUndoRegular />,
            danger: true,
            onClick: () => run(() => gitDiscard(projectPath, [menu.file.path])),
          },
          {
            label: '放弃全部',
            icon: <ArrowUndoRegular />,
            danger: true,
            onClick: () => run(() => gitDiscardAll(projectPath)),
          },
        ]
    : [];

  // 未初始化
  if (gitStatus && !gitStatus.initialized) {
    return (
      <div className="repository">
        <div className="repository-init">
          <p>Git 是版本管理工具，可以保存项目的每次历史版本，方便随时回顾或恢复到之前的某个状态。</p>
          <p>初始化后，只需「暂存 → 提交」两步，就能把当前的修改保存为一个历史记录。</p>
          <Button
            appearance="primary"
            icon={<BranchForkRegular />}
            disabled={busy}
            onClick={() => {
              setGitignore(DEFAULT_GITIGNORE);
              setInitOpen(true);
            }}
          >
            初始化仓库
          </Button>
        </div>

        {initOpen ? (
          <div className="modal-backdrop" onClick={() => setInitOpen(false)}>
            <div className="modal-surface" onClick={(e) => e.stopPropagation()}>
              <h2 className="modal-title">初始化仓库</h2>
              <p className="confirm-message">
                初始化将在项目目录创建 git 仓库。默认只跟踪场景文本文件，其余资源 (图片/音频等) 会被忽略。
                如需调整可编辑下方 .gitignore 内容：
              </p>
              <Textarea
                className="gitignore-editor"
                value={gitignore}
                onChange={(_, data) => setGitignore(data.value)}
                rows={7}
                disabled={busy}
              />
              {error ? <p className="prompt-error">{error}</p> : null}
              <div className="modal-actions">
                <Button
                  appearance="primary"
                  disabled={busy}
                  onClick={() =>
                    void run(() => gitInit(projectPath, gitignore)).then((ok) => {
                      if (ok) setInitOpen(false);
                    })
                  }
                >
                  初始化
                </Button>
                <Button appearance="secondary" disabled={busy} onClick={() => setInitOpen(false)}>
                  取消
                </Button>
              </div>
            </div>
          </div>
        ) : null}
      </div>
    );
  }

  const staged = gitStatus?.staged ?? [];
  const unstaged = gitStatus?.unstaged ?? [];

  return (
    <div className="repository">
      <div className="repository-commit">
        <Textarea
          ref={commitRef}
          className="commit-editor"
          placeholder="描述本次提交的内容…"
          value={message}
          resize="none"
          onChange={(_, data) => {
            commitDraftUpdate(data.value);
            autoGrow();
          }}
          disabled={busy}
        />
        <div className="repository-commit-actions">
          <Button
            appearance="primary"
            icon={<CheckmarkRegular />}
            disabled={busy || message.trim().length === 0 || staged.length === 0}
            onClick={tryCommit}
          >
            提交
          </Button>
          <Button appearance="secondary" icon={<HistoryRegular />} disabled={busy} onClick={() => setHistoryOpen(true)}>
            查看历史
          </Button>
        </div>
      </div>

      <div className="repository-lists">
        <div className="repository-section">
          <div className="repository-section-title">暂存项 ({staged.length})</div>
          {staged.length === 0 ? (
            <div className="muted repository-empty-list">暂无已暂存的更改</div>
          ) : (
            staged.map((f) => fileRow(f, 'staged'))
          )}
        </div>
        <div className="repository-section">
          <div className="repository-section-title">更改项 ({unstaged.length})</div>
          {unstaged.length === 0 ? (
            <div className="muted repository-empty-list">工作区没有更改</div>
          ) : (
            unstaged.map((f) => fileRow(f, 'unstaged'))
          )}
        </div>
      </div>

      {menu ? (
        <>
          <div
            className="context-menu-backdrop"
            onClick={() => setMenu(null)}
            onContextMenu={(e) => {
              e.preventDefault();
              setMenu(null);
            }}
          />
          <div className="context-menu" style={{ left: menu.x, top: menu.y }}>
            {menuItems.map((item) => (
              <button
                key={item.label}
                className={`context-menu-item${item.danger ? ' danger' : ''}`}
                onClick={() => {
                  setMenu(null);
                  item.onClick();
                }}
              >
                {item.icon}
                {item.label}
              </button>
            ))}
          </div>
        </>
      ) : null}

      {identityOpen ? (
        <div className="modal-backdrop" onClick={() => setIdentityOpen(false)}>
          <div className="modal-surface small-surface" onClick={(e) => e.stopPropagation()}>
            <h2 className="modal-title">设置提交身份</h2>
            <p className="confirm-message">首次提交需要填写作者姓名和邮箱，将写入此项目的 git 配置。</p>
            <div className="prompt-field">
              <span className="settings-label">姓名</span>
              <Input
                value={identity.name}
                placeholder="你的名字"
                onChange={(_, data) => setIdentity((v) => ({ ...v, name: data.value }))}
                disabled={busy}
              />
            </div>
            <div className="prompt-field">
              <span className="settings-label">邮箱</span>
              <Input
                value={identity.email}
                placeholder="you@example.com"
                onChange={(_, data) => setIdentity((v) => ({ ...v, email: data.value }))}
                disabled={busy}
              />
            </div>
            {error ? <p className="prompt-error">{error}</p> : null}
            <div className="modal-actions">
              <Button
                appearance="primary"
                disabled={busy || !identity.name.trim() || !identity.email.trim()}
                onClick={() => void submitIdentity()}
              >
                保存并提交
              </Button>
              <Button appearance="secondary" disabled={busy} onClick={() => setIdentityOpen(false)}>
                取消
              </Button>
            </div>
          </div>
        </div>
      ) : null}

      {historyOpen ? <GitHistoryDialog onClose={() => setHistoryOpen(false)} /> : null}

      {error && !initOpen && !identityOpen ? (
        <div className="modal-backdrop" onClick={() => setError(null)}>
          <div className="modal-surface small-surface" onClick={(e) => e.stopPropagation()}>
            <h2 className="modal-title">操作失败</h2>
            <p className="confirm-message">{error}</p>
            <div className="modal-actions">
              <Button appearance="primary" onClick={() => setError(null)}>
                确定
              </Button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}
